#!/usr/bin/env python3
"""Read-only audit: wikilinks under ~/obsidian/projects/ whose target note
exists nowhere in the vault. No writes anywhere."""
import os, re, json, collections

VAULT = os.path.expanduser("~/obsidian")
SCOPE = os.path.join(VAULT, "projects")

# ---------- vault index ----------
all_files = []          # every file in the vault (any extension)
for root, dirs, files in os.walk(VAULT):
    dirs[:] = [d for d in dirs if d not in (".git", ".obsidian")]
    for f in files:
        all_files.append(os.path.relpath(os.path.join(root, f), VAULT))

def norm(p):
    p = p.replace("\\", "/").lstrip("./")
    return re.sub(r"/+", "/", p)

md_rel = [p for p in all_files if p.endswith(".md")]

# keys: lowercase vault-relative path -> real path
by_path = {}
for p in all_files:
    by_path.setdefault(norm(p).lower(), p)
# bare-name (filename) index, and filename-without-extension index
by_name = collections.defaultdict(list)
by_stem = collections.defaultdict(list)
for p in all_files:
    b = os.path.basename(p)
    by_name[b.lower()].append(p)
    stem = b[:-3] if b.lower().endswith(".md") else os.path.splitext(b)[0]
    by_stem[stem.lower()].append(p)

# candidate keys for a bare name that has no extension at all
def ext_variants(t):
    out = [t]
    if not os.path.splitext(t)[1]:
        out.append(t + ".md")
    return out

def resolve(raw, linker):
    """Return (real_path, how) or (None, why)."""
    linker_dir = os.path.dirname(linker)
    has_slash = "/" in raw.rstrip("/").rstrip("|")
    for t in ext_variants(norm(raw)):
        tl = t.lower()
        # vault-relative
        if tl in by_path:
            return by_path[tl], "vault-relative"
        # relative to the linking note's folder (Obsidian relative-path mode)
        if linker_dir:
            rel = norm(os.path.join(linker_dir, t)).lower()
            rel = re.sub(r"^\.\./", "", rel)
            if rel in by_path:
                return by_path[rel], "same-folder"
        # suffix match on a slashed path (folder/... tail)
        if tl.startswith("/"):
            if tl.lstrip("/") in by_path:
                return by_path[tl.lstrip("/")], "vault-relative"
    if not has_slash:
        base = os.path.basename(norm(raw)).lower()
        if base in by_name:
            return by_name[base][0], "filename-anywhere"
        stem = base[:-3] if base.endswith(".md") else os.path.splitext(base)[0]
        if stem in by_stem:
            return by_stem[stem][0], "filename-anywhere"
    else:
        # tail-name fallback for a slashed target
        base = os.path.basename(norm(raw)).lower()
        if base in by_name:
            return by_name[base][0], "tail-filename"
        stem = base[:-3] if base.endswith(".md") else os.path.splitext(base)[0]
        if stem in by_stem:
            return by_stem[stem][0], "tail-filename"
    return None, "missing"

# ---------- link extraction ----------
LINK = re.compile(r"!?\[\[([^\[\]]{1,300})\]\]")
FENCE = re.compile(r"^\s{0,3}(```|~~~)")
INLINE = re.compile(r"(`+)(?:[^`]|\n)*?\1")  # inline code spans

def strip_code(text):
    out, in_fence, fence_tok = [], False, None
    for line in text.split("\n"):
        m = FENCE.match(line)
        if m:
            tok = m.group(1)
            if not in_fence:
                in_fence, fence_tok = True, tok
            elif tok == fence_tok:
                in_fence, fence_tok = False, None
            out.append("" if in_fence else line)
            continue
        out.append("" if in_fence else line)
    return "\n".join(out)

def inline_code_spans(text):
    """char offsets covered by inline code, so we can drop links inside them"""
    spans = []
    for m in re.finditer(r"`+", text):
        spans.append((m.start(), m.end()))
    # pair up runs of backticks: content between an opening run and a matching closing run
    covered = []
    i = 0
    lines = []
    # per-line pairing (inline code does not span lines in CommonMark when unbalanced)
    for ln, line in enumerate(text.split("\n")):
        runs = [(m.start() + sum(len(l) + 1 for l in lines[:ln]), m) for m in re.finditer(r"`+", line)]
        # offset fix: compute absolute start properly below
        pass
    return covered

# simpler + robust: do per-line inline-code stripping before extracting links
def drop_inline_code(line):
    # remove balanced inline code spans; leave the line's rest intact
    prev = None
    while prev != line:
        prev = line
        line = re.sub(r"(`+)(?!`)(.+?)(?<!`)\1(?!`)", lambda m: " " * len(m.group(0)), line)
    # unterminated opening run -> treat to end of line as code
    m = re.search(r"`+", line)
    return line

# The naive sub above already handles balanced spans. Unterminated runs are rare;
# detect and blank them too.
def blank_unterminated(line):
    runs = list(re.finditer(r"`+", line))
    # greedily pair
    used = [False] * len(runs)
    i = 0
    while i < len(runs):
        j = i + 1
        while j < len(runs) and len(runs[j].group(0)) != len(runs[i].group(0)):
            used[i] = False
            j += 1
            break
        if j < len(runs) and len(runs[j].group(0)) == len(runs[i].group(0)):
            used[i] = used[j] = True
            i = j + 1
        else:
            i += 1
    for k, r in enumerate(runs):
        if not used[k]:
            line = line[:r.start()] + " " * (len(line) - r.start())
            break
    return line

results = collections.OrderedDict()   # target-as-written -> first linker
resolved_how = collections.Counter()
counts = {"notes": 0, "links": 0, "skipped_heading": 0, "skipped_alias_only": 0}
tail_only = {}   # resolved only by tail-filename
case_only = {}   # resolved only case-insensitively

scope_notes = []
for root, dirs, files in os.walk(SCOPE):
    dirs[:] = [d for d in dirs if d not in (".git", ".obsidian")]
    for f in sorted(files):
        if f.endswith(".md"):
            scope_notes.append(os.path.relpath(os.path.join(root, f), VAULT))

for rel in sorted(scope_notes):
    abs_p = os.path.join(VAULT, rel)
    try:
        raw_text = open(abs_p, encoding="utf-8", errors="replace").read()
    except OSError as e:
        print("READ_FAIL", rel, e)
        continue
    counts["notes"] += 1
    text = strip_code(raw_text)
    for line in text.split("\n"):
        line = drop_inline_code(line)
        for m in LINK.finditer(line):
            target = m.group(1).strip()
            if not target:
                continue
            counts["links"] += 1
            t = target
            # alias / embed size / block id
            t = re.split(r"\|", t)[0].strip()
            t = re.split(r"#", t)[0].strip()
            t = re.split(r"\^", t)[0].strip()
            if t == "":
                counts["skipped_heading"] += 1
                continue
            real, how = resolve(t, rel)
            if real:
                resolved_how[how] += 1
                if how == "tail-filename":
                    tail_only.setdefault(t, (rel, real))
            else:
                if target not in results:
                    results[target] = rel

print(json.dumps({"counts": dict(counts), "resolved": dict(resolved_how),
                  "scope_notes": len(scope_notes),
                  "vault_md": len(md_rel), "vault_all": len(all_files)}, indent=1))
print("\n=== MISSING (deduped by target as written) ===")
for tgt, linker in results.items():
    print(f"- [[{tgt}]] — {linker}")
print(f"\ntotal distinct missing targets: {len(results)}")
if tail_only:
    print("\n=== resolved ONLY by tail filename (slashes present) ===")
    for t, (l, r) in tail_only.items():
        print(f"[[{t}]] in {l} -> {r}")

